TOKEN = re.compile(r"\{\{ ([a-z_]+) \}\}")


def rgb(value: str) -> str:
    return ", ".join(str(int(value[index : index + 2], 16)) for index in (1, 3, 5))


def context() -> dict[str, str]:
    palette = tomllib.loads(PALETTE_PATH.read_text())
    colors = {key: value for key, value in palette.items() if key != "mode"}
    values = dict(colors)
    values.update({f"{key}_rgb": rgb(value) for key, value in colors.items()})
    return values


def render(template: str, values: dict[str, str]) -> str:
    def replace(match: re.Match[str]) -> str:
        key = match.group(1)
        if key not in values:
            raise ValueError(f"unknown palette token: {key}")
        return values[key]

    return TOKEN.sub(replace, template)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if generated files are stale")
    args = parser.parse_args()

    values = context()
    if not args.check:
        OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    stale = []
    for filename, template in TEMPLATES.items():
        path = OUTPUT_DIR / filename
        content = render(template, values)
        if args.check:
            if not path.is_file() or path.read_text() != content:
                stale.append(filename)
        else:
            path.write_text(content)

    if stale:
        print(f"Stale generated integrations: {', '.join(stale)}", file=sys.stderr)
        raise SystemExit(1)

    if not args.check:
        print(f"Generated {len(TEMPLATES)} optional integrations.")


if __name__ == "__main__":
    main()
